-- Reglas tributarias de Brasil, México, Ecuador y Uruguay en borrador, con fuente. Ninguna está verificada: requieren revisión de un contador.
insert into public.ai_knowledge (kind, area, country_code, topic, title, summary, source_name, source_url, license, lang, status) values
('tax_rule','impuestos','BR','simples_nacional','Simples Nacional en Brasil: límites de ingresos',
$k$El Simples Nacional es un régimen unificado que reúne varios tributos federales, estaduales y municipales en una sola guía (DAS), regulado por la Ley Complementar 123/2006. Según las preguntas frecuentes de la Receita Federal y fuentes de apoyo, el límite de receita bruta anual es de R$ 4,8 millones; la microempresa llega a R$ 360 mil. Para ICMS e ISS existe un sublímite de R$ 3,6 millones: por encima, esos tributos se recaudan fuera del DAS. Fuentes de apoyo mencionan proyectos de ley para elevar los límites, sin aprobación confirmada. Confirmar valores vigentes y la tabla por anexo (comercio, industria, servicios) en el Portal do Simples Nacional o con un contador.$k$,
'Receita Federal, Perguntão Simples Nacional','https://www8.receita.fazenda.gov.br/simplesnacional/arquivos/manual/perguntaosn.pdf',
'Material informativo de la Receita Federal de Brasil y fuentes de apoyo (Contabilizei, Agilize); no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','impuestos','BR','mei','MEI en Brasil: microemprendedor individual',
$k$El Microempreendedor Individual (MEI) es la categoría más pequeña del Simples Nacional. Según el Perguntão MEI de la Receita Federal, el límite de receita bruta anual es de R$ 81.000 (proporcional en el año de inicio de actividad); superarlo implica desenquadramiento. El MEI no puede tener socios y puede contratar un solo empleado. Existen proyectos de ley que proponen ampliar el límite, sin aprobación confirmada en las fuentes revisadas. Las obligaciones (DAS mensual, DASN-SIMEI anual, emisión de nota fiscal) deben confirmarse en el Portal do Simples Nacional.$k$,
'Receita Federal, Perguntão MEI','https://www8.receita.fazenda.gov.br/SimplesNacional/Arquivos/pergunta-resposta/PerguntaoMEI.pdf',
'Material informativo de la Receita Federal de Brasil; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','impuestos','BR','reforma_consumo','Reforma tributaria del consumo en Brasil: CBS e IBS en transición',
$k$Brasil está reemplazando PIS, COFINS, IPI, ICMS e ISS por un IVA dual: la CBS (federal, administrada por la Receita Federal) y el IBS (estadual y municipal, con Comité Gestor). La base legal es la Emenda Constitucional 132/2023 y las Leyes Complementares 214/2025 y 227/2026. En 2026 es año de pruebas: los documentos fiscales electrónicos deben mostrar alícuotas de prueba de 0,9 % de CBS y 0,1 % de IBS, que se compensan con los tributos actuales; la transición avanza hasta 2033. Una noticia de julio de 2026 indica que la Receita aplazó el cronograma de destaque en los documentos, y las alícuotas definitivas aún dependen de resolución del Senado. Confirmar plazos y obligaciones vigentes en la página de la reforma de la Receita Federal.$k$,
'Receita Federal, Reforma Tributária do Consumo','https://www.gov.br/receitafederal/pt-br/acesso-a-informacao/acoes-e-programas/programas-e-atividades/reforma-tributaria-do-consumo',
'Material informativo de la Receita Federal y fuentes de prensa (Agência Brasil, Senado); no declaran licencia abierta. Resumido con palabras propias, con enlace a la fuente. Tema en cambio constante: pendiente de confirmación con contador.','es','draft'),
('tax_rule','impuestos','MX','iva_isr','IVA e ISR en México: tasas generales',
$k$En México la tasa general del IVA es de 16 % en la mayor parte del territorio, y el ISR de personas morales es de 30 % según fuentes de apoyo para 2026; las personas físicas tributan con tarifa progresiva. Los pagos provisionales de ISR e IVA se presentan a más tardar el día 17 del mes siguiente, y la declaración anual de personas morales vence el 31 de marzo. Estas fuentes no son del SAT: confirmar tasas, tarifas y fechas en el SAT o con un contador.$k$,
'Alegra México, cambios fiscales para empresas','https://blog.alegra.com/mexico/cambios-fiscales-para-empresas/',
'Fuente secundaria (Alegra, BBVA); no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador y con el SAT.','es','draft'),
('tax_rule','impuestos','MX','resico','RESICO en México: Régimen Simplificado de Confianza',
$k$El RESICO para personas físicas con actividad empresarial, profesional o arrendamiento aplica tasas fijas de ISR de 1 % a 2,5 % sobre ingresos efectivamente cobrados, siempre que los ingresos anuales no superen 3,5 millones de pesos. Fuentes de apoyo señalan también un RESICO para personas morales con límite de 35 millones de pesos; no pueden tributar quienes sean socios o accionistas en ciertos supuestos. Confirmar requisitos y límites vigentes en el SAT.$k$,
'Facturama, RESICO régimen simplificado de confianza','https://facturama.mx/blog/resico-regimen-simplificado-confianza/',
'Fuente secundaria (Facturama, Alegra); no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador y con el SAT.','es','draft'),
('tax_rule','contabilidad','MX','cfdi','Factura electrónica CFDI 4.0 en México',
$k$Según fuentes de apoyo, el CFDI 4.0 es el único estándar de factura electrónica válido en México en 2026. Para deducir un gasto en ISR o acreditar IVA se requiere el XML válido del CFDI emitido por el proveedor. También se emite CFDI por nómina y pagos. Confirmar reglas y complementos vigentes en el SAT (Resolución Miscelánea Fiscal 2026).$k$,
'Alegra México, cambios fiscales para empresas','https://blog.alegra.com/mexico/cambios-fiscales-para-empresas/',
'Fuente secundaria (Alegra, BizLatinHub); no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador y con el SAT.','es','draft'),
('tax_rule','impuestos','EC','iva','IVA en Ecuador: tarifa general del 15 %',
$k$En Ecuador la tarifa general del IVA pasó de 12 % a 15 % desde el 1 de abril de 2024. Una consulta tributaria de diciembre de 2025 indica que la tarifa de 15 % se mantiene para 2026 y que los contribuyentes deben aplicarla hasta que exista una modificación legal expresa o decreto del Ejecutivo. Confirmar tarifa vigente y bienes con tarifa 0 % en el SRI.$k$,
'Cámara de Comercio de Quito, Consulta Tributaria diciembre 2025','https://ccq.ec/wp-content/uploads/2026/02/Consulta-Tributaria-Diciembre-2025.pdf',
'Fuente secundaria (gremio empresarial, prensa); no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador y con el SRI.','es','draft'),
('tax_rule','impuestos','EC','rimpe','RIMPE en Ecuador: régimen para emprendedores y negocios populares',
$k$El Régimen Simplificado para Emprendedores y Negocios Populares (RIMPE) cubre a personas y sociedades con ingresos brutos anuales de hasta USD 300.000, según una fuente de apoyo. Los contribuyentes RIMPE Emprendedores declaran y pagan el IVA de forma semestral. Confirmar categorías, límites y tarifas vigentes en el SRI.$k$,
'LookupTax, Ecuador VAT guidelines','https://lookuptax.com/docs/country/ecuador-vat-guidelines-indirect-tax',
'Fuente secundaria; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador y con el SRI.','es','draft'),
('tax_rule','contabilidad','EC','facturacion_electronica','Facturación electrónica y declaraciones en Ecuador',
$k$Fuentes de apoyo indican que la facturación electrónica es obligatoria en Ecuador y que la declaración de IVA mensual se presenta entre los días 10 y 28 del mes siguiente según el noveno dígito del RUC; los contribuyentes con declaración semestral lo hacen en enero y julio. Confirmar calendario y obligados en el SRI.$k$,
'Andersen Ecuador, TIPS obligaciones empresariales enero 2026','https://ec.andersen.com/wp-content/uploads/2025/12/TIPS-41-Obligaciones-empresariales-enero-2026.pdf',
'Fuente secundaria (firma de asesoría); no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador y con el SRI.','es','draft'),
('tax_rule','impuestos','UY','iva','IVA en Uruguay: tasas',
$k$En Uruguay la tasa básica del IVA es de 22 % y la tasa mínima es de 10 % para una lista legal cerrada (por ejemplo alimentos básicos y medicamentos); las exportaciones tienen tasa cero. El tributo lo administra la Dirección General Impositiva (DGI) y su norma base está en el Texto Ordenado de la DGI. Confirmar bienes y servicios a tasa mínima y plazos de declaración en la DGI.$k$,
'Uruguay XXI, sistema tributario','https://www.uruguayxxi.gub.uy/en/invest/investors-guide/tax-system/',
'Fuente de agencia pública (Uruguay XXI) y de apoyo (Kintsugi, LookupTax); no declaran licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','impuestos','UY','irae','IRAE en Uruguay: impuesto a las rentas de actividades económicas',
$k$El Impuesto a las Rentas de las Actividades Económicas (IRAE) tiene una tasa de 25 % sobre las rentas netas de fuente uruguaya, según Uruguay XXI, que también menciona el Impuesto al Patrimonio con tasa de 1,5 % para empresas. Confirmar regímenes simplificados (literal E, monotributo) y anticipos en la DGI.$k$,
'Uruguay XXI, sistema tributario','https://www.uruguayxxi.gub.uy/en/invest/investors-guide/tax-system/',
'Fuente de agencia pública; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('tax_rule','contabilidad','UY','cfe','Comprobante Fiscal Electrónico (CFE) en Uruguay',
$k$Según una fuente de apoyo, la facturación electrónica mediante Comprobantes Fiscales Electrónicos (CFE) es obligatoria para todos los contribuyentes bajo la Resolución DGI 798/2012, e incluye e-Remito y e-Resguardo. Esto es afirmación de una fuente secundaria: confirmar quiénes están obligados y cronograma en la DGI.$k$,
'Sovos, cumplimiento del IVA en Uruguay','https://sovos.com/es/iva/reglas-fiscales/cumplimiento-del-iva-en-uruguay/',
'Fuente secundaria; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador y con la DGI.','es','draft');
